function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let z;
try { z = require("zod"); } catch (e) { broken("cannot load zod: " + e.message); }
if (typeof z.toJSONSchema !== "function") broken("z.toJSONSchema is not a function");
const truthy = z.toJSONSchema(z.boolean().prefault(true), { io: "input" });
if (truthy.default !== true) broken("prefault(true) is not emitted as default: " + JSON.stringify(truthy));
const cases = [[z.boolean().prefault(false), false], [z.number().prefault(0), 0], [z.string().prefault(""), ""]];
const missing = [];
for (const [s, v] of cases) {
  const js = z.toJSONSchema(s, { io: "input" });
  if (!("default" in js)) missing.push(JSON.stringify(v));
  else if (js.default !== v) broken("prefault(" + JSON.stringify(v) + ") emitted default " + JSON.stringify(js.default));
}
if (missing.length === cases.length) symptom("falsy prefault values " + missing.join(", ") + " are omitted as default from toJSONSchema io input");
if (missing.length) broken("only some falsy prefaults are omitted: " + missing.join(", "));
console.log("OK: falsy prefault values are emitted as default in toJSONSchema io input");

